def future_value(principal, annual_rate, years, periods_per_year):
    n = periods_per_year
    periodic = 1 + (annual_rate / 100) / n
    factor = pow(periodic, n * years)
    return round(principal * factor, 2)

def future_value(principal, annual_rate, years, periods_per_year):

    r = annual_rate / 100
    n = periods_per_year

    result = float(principal) * (1.0 + r / n) ** (n * years)

    return float(round(result, 2))
